    private static JSONObject settings(String build,String view)throws Exception{return SketchHumanFigure.settings(new JSONObject().put("build",build).put("view",view).put("clothingStyle","tailored").put("faceStyle","angular").put("shading","soft").put("size",1.25).put("floorY",.85).put("skinColor","#FFA46F55").put("coatColor","#FF75654F").put("hairColor","#FF272A32"));}
    private static JSONObject document(int fps)throws Exception{return SketchDocument.create(new JSONObject().put("sketchId","lift_anatomy").put("width",1280).put("height",720).put("fps",fps).put("frameCount",96));}
    private static JSONArray objects(JSONObject d)throws Exception{return d.getJSONArray("layers").getJSONObject(0).getJSONArray("objects");}
    private static JSONObject operation(JSONObject settings)throws Exception{return new JSONObject().put("type","add_human_animation").put("layerId","layer_1").put("actorId","adult").put("preset","lift").put("settings",settings);}
    private static JSONObject actor(JSONObject d)throws Exception{return SketchDocument.object(d,"adult_rig");}
    private static double[] local(SketchHumanFigure.Skeleton s,double[] p){double[] v={p[0]-s.hip[0],p[1]-s.hip[1],p[2]-s.hip[2]},n=s.camera.normal();double t=-Math.toRadians(s.lean),c=Math.cos(t),q=Math.sin(t),dot=v[0]*n[0]+v[1]*n[1]+v[2]*n[2];return new double[]{v[0]*c+(n[1]*v[2]-n[2]*v[1])*q+n[0]*dot*(1-c),v[1]*c+(n[2]*v[0]-n[0]*v[2])*q+n[1]*dot*(1-c),v[2]*c+(n[0]*v[1]-n[1]*v[0])*q+n[2]*dot*(1-c)};}
    private static double length(double[] a,double[] b){double total=0;for(int i=0;i<3;i++)total+=(a[i]-b[i])*(a[i]-b[i]);return Math.sqrt(total);}
    private static Region coat(String build,String view,JSONObject pose)throws Exception{
        JSONObject s=settings(build,view).put("size",1).put("floorY",.85),p=SketchDocument.copy(pose).put("bodyLean",0),d=document(24);d.put("frameCount",1);SketchHumanFigure.draw(d,d.getJSONArray("layers").getJSONObject(0),"coatprobe",s,p,0);
        JSONArray all=objects(d);for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getString("id").equals("coatprobe_coat_0")){Region r=new Region();r.setPath(SketchFrameRenderer.path(all.getJSONObject(i).getJSONArray("commands"),1280,720),new Region(0,0,1280,720));return r;}throw new AssertionError("Missing native coat");
    }
    private static boolean deepInside(Region r,int x,int y){for(int dx:new int[]{-4,0,4})for(int dy:new int[]{-4,0,4})if(!r.contains(x+dx,y+dy))return false;return true;}
    // Independent inscribed elliptical torso core from the actual front/profile
    // cross-sections. The rectangle intersection alone would falsely reject a
    // point outside a rounded flank. Inset3px allows garment thickness.
    private static double radius(Region region,int y){int left=0,right=0;while(left<80&&region.contains(640-left,y))left++;while(right<80&&region.contains(640+right,y))right++;return Math.max(1,Math.min(left,right)-3);}
    private static void clearArm(String label,SketchHumanFigure.Skeleton sk,double[] a,double[] b,boolean upper,Region front,Region profile)throws Exception{
        for(int n=upper?5:0;n<=24;n++){double t=n/24d;double[] point=new double[3];for(int k=0;k<3;k++)point[k]=a[k]+(b[k]-a[k])*t;double[] p=local(sk,point);int y=(int)Math.round(612+sk.controls.getDouble("hipY")+p[1]);
            assertFalse(label+" "+(upper?"upper":"forearm")+" t="+t+" inside native front/profile coat core "+Arrays.toString(p),deepInside(front,(int)Math.round(640+p[0]),y)&&deepInside(profile,(int)Math.round(640+p[2]),y)&&p[0]*p[0]/Math.pow(radius(front,y),2)+p[2]*p[2]/Math.pow(radius(profile,y),2)<1);
        }
    }
    @Test public void generatedLiftKeepsBothArmSegmentsOutOfNativeFrontAndProfileCoatInteriors()throws Exception {
        for(int fps:new int[]{24,30,60}){JSONArray program=SketchHumanPresets.create("lift",96,fps);Map<String,JSONArray> perView=new HashMap<>();for(String view:VIEWS)perView.put(view,SketchHumanPresets.createForView("lift",96,fps,new JSONObject(),view));
            for(int frame=0;frame<96;frame++){JSONObject pose=SketchHumanAnimation.poseAt(program,frame);for(String build:BUILDS){Region front=coat(build,"front",pose),profile=coat(build,"right",pose);for(String view:VIEWS){SketchHumanFigure.Skeleton sk=SketchHumanFigure.skeleton(settings(build,view),SketchHumanAnimation.poseAt(perView.get(view),frame));String label=build+"/"+view+"/"+fps+"/"+frame;
                clearArm(label+" near",sk,sk.nearShoulder,sk.nearElbow,true,front,profile);clearArm(label+" near",sk,sk.nearElbow,sk.nearHand,false,front,profile);clearArm(label+" far",sk,sk.farShoulder,sk.farElbow,true,front,profile);clearArm(label+" far",sk,sk.farElbow,sk.farHand,false,front,profile);
            }}}
        }
    }
    @Test public void liftHandsReachForwardAndArmMotionKeepsBonesSolesAndContinuousLean()throws Exception {
        for(int fps:new int[]{24,30,60})for(String view:VIEWS)for(String build:BUILDS){JSONObject s=settings(build,view);JSONArray poses=SketchHumanPresets.createForView("lift",96,fps,new JSONObject(),view);assertEquals("Keep the existing sparse9-key preset clock",9,poses.length());SketchHumanFigure.Skeleton previous=null;
            for(int frame=0;frame<96;frame++){JSONObject p=SketchHumanAnimation.poseAt(poses,frame);SketchHumanFigure.Skeleton sk=SketchHumanFigure.skeleton(s,p);
                for(double[][] bones:new double[][][]{{sk.nearShoulder,sk.nearElbow},{sk.farShoulder,sk.farElbow}})assertEquals(76,length(bones[0],bones[1]),1e-8);
                assertEquals(70,length(sk.nearElbow,sk.nearHand),1e-8);assertEquals(70,length(sk.farElbow,sk.farHand),1e-8);assertEquals(90,length(sk.leftHip,sk.leftKnee),1e-8);assertEquals(90,length(sk.rightHip,sk.rightKnee),1e-8);assertEquals(86,length(sk.leftKnee,sk.leftAnkle),1e-8);assertEquals(86,length(sk.rightKnee,sk.rightAnkle),1e-8);
                assertArrayEquals(new double[]{-28,0,-9},sk.leftFoot,0);assertArrayEquals(new double[]{28,0,9},sk.rightFoot,0);
                if(previous!=null){assertTrue("Continuous near elbow through anticipation/straight rest/lean",length(previous.nearElbow,sk.nearElbow)<7);assertTrue("Continuous far elbow",length(previous.farElbow,sk.farElbow)<7);}previous=sk;
                if(frame==48){assertTrue("Lifting hands belong ahead of the trunk",local(sk,sk.nearHand)[2]>40);assertTrue("Both hands lift forward",local(sk,sk.farHand)[2]>40);assertTrue("Exercise nonzero torso lean",Math.abs(sk.lean)>1);
                    for(double[][] arm:new double[][][]{{sk.nearShoulder,sk.nearElbow,sk.nearHand},{sk.farShoulder,sk.farElbow,sk.farHand}}){double[] shoulder=local(sk,arm[0]),elbow=local(sk,arm[1]),wrist=local(sk,arm[2]);String label=build+"/"+view+"/"+fps;
                        assertTrue(label+" carrying elbow must sit below its wrist, rather than above it in a rowing pose",elbow[1]-wrist[1]>2);
                        assertTrue(label+" upper arm should descend alongside the body instead of spreading horizontally",elbow[1]-shoulder[1]>Math.abs(elbow[0]-shoulder[0]));
                    }}
            }
        }
    }
    private static String otherPresets()throws Exception{JSONArray rows=new JSONArray();for(String name:SketchHumanPresets.NAMES)if(!name.equals("lift"))for(int fps:new int[]{24,30,60})for(String view:VIEWS)rows.put(SketchHumanPresets.createForView(name,96,fps,new JSONObject(),view));return SketchDocument.sha256(SketchDocument.canonical(rows).getBytes(StandardCharsets.UTF_8));}
    private static JSONObject oldDocument(String build,String view)throws Exception{JSONObject d=document(24);SketchHumanAnimation.apply(d,operation(settings(build,view)).put("poses",new JSONArray(OLD_POSES)).put("blinkTrack",SketchHumanBlink.defaults()));return d;}
    private static String pixels(Bitmap b)throws Exception{int[] p=new int[b.getWidth()*b.getHeight()];b.getPixels(p,0,b.getWidth(),0,0,b.getWidth(),b.getHeight());ByteBuffer bytes=ByteBuffer.allocate(p.length*4);for(int c:p)bytes.putInt(c);return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes.array()));}
    @Test public void capturePreRepairExplicitLiftPixelsAndUnaffectedPresetPrograms()throws Exception {
        String path=System.getProperty("videostudio.lift.captureLegacy");if(path==null)return;File root=new File(path);assertFalse(root.exists());assertTrue(root.mkdirs());JSONArray hashes=new JSONArray();
        for(String build:BUILDS)for(String view:VIEWS){JSONObject d=oldDocument(build,view);try(SketchFrameRenderer r=new SketchFrameRenderer(RuntimeEnvironment.getApplication(),d)){for(int frame:new int[]{0,48,95}){Bitmap b=r.render(frame);try{hashes.put(pixels(b));try(OutputStream out=new FileOutputStream(new File(root,build+"-"+view+"-"+frame+".png"))){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}}finally{b.recycle();}}}}
        Files.write(new File(root,"Baseline.json").toPath(),new JSONObject().put("pixelHashes",hashes).put("otherPresets",otherPresets()).toString(2).getBytes(StandardCharsets.UTF_8));
    }
    @Test public void savedOldLiftInkAndAllOtherPresetProgramsRemainUnchanged()throws Exception {
        assertEquals(OTHER_PRESETS,otherPresets());assertEquals(36,OLD_PIXELS.length);int n=0;for(String build:BUILDS)for(String view:VIEWS){JSONObject d=oldDocument(build,view);String frozen=SketchDocument.canonical(d);try(SketchFrameRenderer r=new SketchFrameRenderer(RuntimeEnvironment.getApplication(),d)){for(int frame:new int[]{0,48,95}){Bitmap b=r.render(frame);try{assertEquals(build+"/"+view+"/"+frame,OLD_PIXELS[n++],pixels(b));String originals=System.getProperty("videostudio.lift.originalPngs");if(originals!=null){Bitmap original=BitmapFactory.decodeFile(new File(originals,build+"-"+view+"-"+frame+".png").getAbsolutePath());assertNotNull(original);try{assertTrue("Saved pre-repair retained programme must equal its actual original PNG",b.sameAs(original));}finally{original.recycle();}}}finally{b.recycle();}}}assertEquals(frozen,SketchDocument.canonical(d));}
    }
    @Test public void explicitOverridesAndExplicitRetainedPosesRemainAuthoritative()throws Exception {
        JSONObject overrides=new JSONObject().put("nearHandX",28).put("nearHandY",-250).put("nearHandZ",16).put("nearElbowSwivel",130).put("farHandZ",-16).put("farElbowSwivel",-130).put("nearWrist",-35);
        for(String view:VIEWS){JSONArray keys=SketchHumanAnimation.presetPoses("lift",96,30,new JSONObject(),view,overrides);for(int frame=0;frame<96;frame++){JSONObject pose=SketchHumanAnimation.poseAt(keys,frame);for(Iterator<String> names=overrides.keys();names.hasNext();){String name=names.next();assertEquals("Do not silently reroute explicit controls",overrides.getDouble(name),pose.getDouble(name),1e-10);}}}
        JSONObject d=oldDocument("slender","high");assertEquals(SketchDocument.canonical(new JSONArray(OLD_POSES)),SketchDocument.canonical(actor(d).getJSONObject("human").getJSONArray("poses")));
        // Rest and very low-strength authored lift must remain stable near a straight arm.
        for(double strength:new double[]{0,.001,.1})for(String view:VIEWS){JSONArray keys=SketchHumanPresets.createForView("lift",96,60,new JSONObject().put("strength",strength),view);SketchHumanFigure.Skeleton previous=null;for(int frame=0;frame<96;frame++){SketchHumanFigure.Skeleton now=SketchHumanFigure.skeleton(settings("broad",view),SketchHumanAnimation.poseAt(keys,frame));if(previous!=null){assertTrue(length(previous.nearElbow,now.nearElbow)<2);assertTrue(length(previous.farElbow,now.farElbow)<2);}previous=now;}}
    }
    @Test public void historicalOperationReceiptRetriesPreserveOldPoseAndArchivePixels()throws Exception {
        android.content.Context context=RuntimeEnvironment.getApplication();String id="lift_retry_"+UUID.randomUUID();JSONObject create=new JSONObject().put("sketchId",id).put("operationId","create").put("width",1280).put("height",720).put("fps",24).put("frameCount",96);SketchEditOps.execute(context,"sketch_create",create);
        JSONObject op=operation(settings("slender","high")),request=new JSONObject().put("sketchId",id).put("operationId","old_lift").put("expectedRevision",1).put("operations",new JSONArray().put(op));String fingerprint=SketchDocument.sha256(("sketch_edit\n"+SketchDocument.canonical(request)).getBytes(StandardCharsets.UTF_8));JSONObject previous,source;
        try(SketchProjectStore store=new SketchProjectStore(context)){
            // Seed a real pre-upgrade receipt and saved programme, without calling
            // the new generator. This is exactly the product's durable request hash.
            previous=store.mutate(id,"old_lift",1,fingerprint,d->{SketchHumanAnimation.apply(d,SketchDocument.copy(op).put("poses",new JSONArray(OLD_POSES)).put("blinkTrack",SketchHumanBlink.defaults()));return d;});source=store.get(id);
        }
        assertEquals(SketchDocument.canonical(SketchDocument.copy(previous).put("ok",true)),SketchDocument.canonical(SketchEditOps.execute(context,"sketch_edit",request)));
        JSONObject changed=SketchDocument.copy(request);changed.getJSONArray("operations").getJSONObject(0).getJSONObject("settings").put("size",1.1);assertThrows(IllegalStateException.class,()->SketchEditOps.execute(context,"sketch_edit",changed));
        try(SketchProjectStore store=new SketchProjectStore(context)){assertEquals(SketchDocument.canonical(source),SketchDocument.canonical(store.get(id)));}
        SketchPaintArchive.Prepared archive=SketchPaintArchive.prepare(context,new JSONObject().put("sketchId",id).put("expectedRevision",2).put("operationId","archive_old_lift"));JSONObject restore=SketchPaintArchive.restoreFile(context,archive.file,SketchProjectStore.fileHash(archive.file),"restored_"+UUID.randomUUID().toString().replace("-",""),"Old retained lift");
        try(SketchProjectStore store=new SketchProjectStore(context)){JSONObject restored=store.get(restore.getString("sketchId"));assertEquals(SketchDocument.canonical(actor(source).getJSONObject("human")),SketchDocument.canonical(actor(restored).getJSONObject("human")));try(SketchFrameRenderer a=new SketchFrameRenderer(context,source);SketchFrameRenderer b=new SketchFrameRenderer(context,restored)){for(int frame:new int[]{48,95}){Bitmap x=a.render(frame),y=b.render(frame);try{assertTrue("Old retained archive must render identical native pixels",x.sameAs(y));}finally{x.recycle();y.recycle();}}}}
    }
    @Test public void newLiftPropKeysUseRecomputedPalmGripsAndNativeFingersCoverTheHandle()throws Exception {
        for(String build:BUILDS)for(String view:VIEWS)for(String side:new String[]{"near","far"}){
            JSONObject d=document(24),s=settings(build,view).put("size",.9);SketchHumanAnimation.apply(d,operation(s));JSONObject adult=actor(d);SketchActorProp.apply(d,new JSONObject().put("type","add_actor_prop").put("layerId","layer_1").put("propId","held").put("actorId","adult").put("settings",new JSONObject().put("kind","parcel").put("attachment",side).put("scale",.65)));
            JSONObject handle=SketchDocument.object(d,"held_handle_0");handle.put("color","#FFFF2020").put("width",.006);JSONArray first=handle.getJSONArray("commands").getJSONArray(0);
            for(int frame=0;frame<96;frame++){JSONObject pose=SketchHumanAnimation.pose(adult,frame);SketchHumanFigure.Skeleton sk=SketchHumanFigure.skeleton(s,pose);double[] wrist=SketchHumanFigure.project(s,side.equals("near")?sk.nearHand:sk.farHand),elbow=SketchHumanFigure.project(s,side.equals("near")?sk.nearElbow:sk.farElbow);double angle=Math.atan2(wrist[1]-elbow[1],wrist[0]-elbow[0])-Math.PI/2+Math.toRadians(pose.getDouble(side+"Wrist")),x=2*pose.getDouble("handOpen"),y=15+2*pose.getDouble("handOpen");double[] independent={wrist[0]+x*Math.cos(angle)-y*Math.sin(angle),wrist[1]+x*Math.sin(angle)+y*Math.cos(angle)};assertArrayEquals(independent,SketchHumanFigure.grip(s,pose,side.equals("near")),1e-8);
                float[] pinch={(float)(first.getDouble(1)*1280),(float)(first.getDouble(2)*720)};SketchFrameRenderer.matrix(SketchDocument.transformAt(handle,frame),1280,720).mapPoints(pinch);assertEquals(1280*s.getDouble("x")+.9*independent[0],pinch[0],.001);assertEquals(720*s.getDouble("floorY")+.9*independent[1],pinch[1],.001);
            }
            JSONObject before=SketchDocument.copy(d),bare=SketchDocument.copy(d);JSONArray withoutOverlay=new JSONArray(),all=objects(before);for(int i=0;i<all.length();i++)if(!all.getJSONObject(i).getString("id").equals("held_grip"))withoutOverlay.put(all.getJSONObject(i));before.getJSONArray("layers").getJSONObject(0).put("objects",withoutOverlay);JSONObject hand=SketchDocument.copy(SketchDocument.object(bare,"held_grip"));bare.getJSONArray("layers").getJSONObject(0).put("objects",new JSONArray().put(hand));
            try(SketchFrameRenderer behind=new SketchFrameRenderer(RuntimeEnvironment.getApplication(),before);SketchFrameRenderer composed=new SketchFrameRenderer(RuntimeEnvironment.getApplication(),d);SketchFrameRenderer skin=new SketchFrameRenderer(RuntimeEnvironment.getApplication(),bare)){
                for(int frame:new int[]{0,48,95}){Bitmap a=behind.render(frame),b=composed.render(frame),c=skin.render(frame);try{float[] point={(float)(first.getDouble(1)*1280),(float)(first.getDouble(2)*720)};SketchFrameRenderer.matrix(SketchDocument.transformAt(handle,frame),1280,720).mapPoints(point);int covered=0,visible=0;for(int dx=-18;dx<=18;dx++)for(int dy=-18;dy<=18;dy++){int px=Math.round(point[0])+dx,py=Math.round(point[1])+dy;if(a.getPixel(px,py)!=0xFFFF2020)continue;if(Math.abs(dx)<=6&&Math.abs(dy)<=6&&b.getPixel(px,py)==c.getPixel(px,py)&&b.getPixel(px,py)!=0xFFFF2020)covered++;if(b.getPixel(px,py)==0xFFFF2020)visible++;}assertTrue(build+"/"+view+"/"+side+"/"+frame+" native fingers must cover the handle at the new grip",covered>0);assertTrue("Actual handle arc must remain exposed",visible>0);}finally{a.recycle();b.recycle();c.recycle();}}
            }
        }
    }
    @Test public void captureFreshNativeLiftMotionOnlyWhenExplicitlyRequested()throws Exception {
        String path=System.getProperty("videostudio.lift.preview");if(path==null)return;File root=new File(path);assertFalse("Preserve earlier generations",root.exists());assertTrue(root.mkdirs());JSONArray cases=new JSONArray();
        for(String build:BUILDS)for(String view:VIEWS){String id="lift_"+build+"_"+view;File folder=new File(root,id);assertTrue(folder.mkdirs());JSONObject d=document(24),op=operation(settings(build,view)).put("fit",true);SketchHumanAnimation.apply(d,op);SketchDocument.validate(d);String frozen=SketchDocument.canonical(d);write(new File(folder,"operation.json"),op);write(new File(folder,"document.json"),d);write(new File(folder,"program.json"),actor(d).getJSONObject("human"));JSONArray shots=new JSONArray();
            try(SketchFrameRenderer renderer=new SketchFrameRenderer(RuntimeEnvironment.getApplication(),d)){for(int frame=0;frame<96;frame++){Bitmap image=renderer.render(frame);File file=new File(folder,String.format(Locale.ROOT,"frame-%04d.png",frame));try{try(OutputStream out=new FileOutputStream(file)){assertTrue(image.compress(Bitmap.CompressFormat.PNG,100,out));}shots.put(new JSONObject().put("frame",frame).put("sha256",SketchProjectStore.fileHash(file)));}finally{image.recycle();}}}
            assertEquals(frozen,SketchDocument.canonical(d));assertEquals(96,shots.length());cases.put(new JSONObject().put("id",id).put("frameCount",96).put("fps",24).put("width",1280).put("height",720).put("allFramesRendered",true).put("nativeFrames",shots).put("visual","UNREVIEWED").put("motion","UNREVIEWED"));write(new File(root,"Preview-Index.json"),new JSONObject().put("cases",cases).put("count",cases.length()).put("complete",cases.length()==12).put("motion","UNREVIEWED"));System.out.println("LIFT NATIVE "+id+" 96 frames");
        }
    }
    private static void write(File file,JSONObject value)throws Exception{Files.write(file.toPath(),value.toString(2).getBytes(StandardCharsets.UTF_8));}

